# SQL
HTTPFS_SQL = "INSTALL httpfs; LOAD httpfs;"
# terrace:1, semi:2, detached:3, flat:4, other:0
SELECT_ALL_SQL = "select * from prices order by date asc,price asc;"
# DuckDB's csv sniffer defaults all int to BIGINT
# we have DuckDB-WASM configged to avoid BIGINT, so
# we get double instead. So here we spec for INTEGER,
# for type,is_new,duration. Since price and date
# are numerical we'll let them dflt to DOUBLE, which
# suits ImPlot. ImPlot time axes use a 1 sec unit,
# and UKP is in days, so we *86400 in widget scaling
SCHEMA = {
    'price':'DOUBLE',
    'date':'DOUBLE',
    'type':'INTEGER',
    'is_new': 'INTEGER',
    'duration': 'INTEGER'
}
# note the where clause in table_sql: we only want rows
# free of NULL in critical fields.
table_sql = """BEGIN; CREATE TABLE IF NOT EXISTS prices AS
 SELECT price, date, postcode1, postcode2, type, is_new, duration, addr1, addr2
 FROM read_csv_auto('https://datasets-documentation.s3.eu-west-3.amazonaws.com/uk-house-prices/csv/house_prices.csv.gz', types={})
 WHERE COLUMNS('[price|date|postcode?|addr?]') IS NOT NULL
 AND DATE > 1.0; COMMIT;"""
TABLE_SQL = table_sql.format(SCHEMA)

LAUNCH_HTTPFS = dict(
    action="Command",
    query_id="load_and_install_httpfs",
    cname="httpfs_sql",
)

LAUNCH_TABLE = dict(  # raise scanning modal, send scan request to DuckDB
    ui_push="parquet_loading_modal",
    action="Command",
    query_id="create_prices_table",
    cname="table_sql",
)

POP_LOADING = dict(
    ui_pop="LoadingModal"
)

LAUNCH_SELECT_ALL = dict(
    action="Query",
    query_id="select_all_prices",
    cname="select_all_sql",
)


LAUNCH_SELECT_ALL_BATCH = dict(
    action="BatchRequest",
    query_id="select_all_prices",
)


INIT_SEQUENCE = [
    LAUNCH_HTTPFS,
    LAUNCH_TABLE,
    LAUNCH_SELECT_ALL,
    LAUNCH_SELECT_ALL_BATCH,
]

property_types = {
    1:"terrace",
    2:"semi",
    3:"detached",
    4:"flat",
    5:"other"
}

def select_batch_action_generator(count=5):
    while (count > 0):
        qid = f"select_{property_types[count]}_prices"
        ckey = f"{qid}_sql"
        select = dict(action="Query", query_id=qid, cname=ckey)
        batch = dict(action="BatchRequest", query_id=qid)
        yield [select, batch]
        count -= 1

def select_sql_generator(count=5):
    while (count > 0):
        qid = f"select_{property_types[count]}_prices"
        ckey = f"{qid}_sql"
        sql = f"select date,price from prices where type={count};"
        yield [ckey, sql]
        count -= 1

base_curve_dict = dict(
    show_lines=False,
    show_fills=False,
    show_scatter=True,
    xtime=True,
    iso_time=True,
    local_time=True,
    xname="xaxis",
    xscaling="xscale",
    yname="yaxis")

def curve_generator(count=5):
    while (count > 0):
        title = property_types[count]
        qid = f"select_{title}_prices"
        cspec = base_curve_dict.copy()
        cspec.update(dict(title=title, query_id=qid))
        yield dict(rname="Curve", cspec=cspec)
        count -= 1

